    def __init__(self, store, slot_id):
        self._store = store
        self._slot_id = slot_id
        self.closed = False

    @property
    def text(self):
        return self._store.slots[self._slot_id]

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, traceback):
        self.closed = True


class LeaseStore:
